class ReportService:
    def __init__(self, repository: OrderRepository, mailer: EmailClient) -> None:
        self._repository = repository
        self._mailer = mailer

    def order_count(self) -> int:
        return self._repository.count()

    def mail_summary(self, address: str) -> dict[str, str]:
        return self._mailer.send(address, f"{self._repository.count()} orders")
```
Update ReportView to depend only on ReportService and focus on presentation:
```python
class ReportView:
    def __init__(self, service: ReportService, width: int = 40) -> None:
        self._service = service
        self._width = width

    def title(self) -> str:
        return "Orders".center(self._width, "-")

    def describe_customer(self, customer) -> str:
        parts = [
            str(customer.customer_id()),
            customer.name(),
            customer.email(),
            customer.tier(),
        ]
        return " | ".join(parts).ljust(self._width)

    # thin delegations to the service
    def order_count(self) -> int:
        return self._service.order_count()

    def mail_summary(self, address: str) -> dict[str, str]:
        return self._service.mail_summary(address)
```

